"use strict";
// Scattergories (Declarative): a turn-based adaptation of the word game.
// 2-6 players, 3 rounds. Each round has one letter and six categories drawn
// without repeats from the banks below. Players answer in seat order; on
// your turn you submit all six answers as one move {type:"answer",
// answers:[6 strings]} (an empty string is no answer). Answers are hidden
// until the round is scored, then the scored round becomes public in `past`.
//
// Scoring, per category: an answer is normalized by trimming, collapsing
// whitespace and lowercasing. It scores 1 point when it is non-empty, when
// its first word starts with the round letter, and when no other player
// gave the same normalized answer for that category. For the letter test
// only, exactly one leading article ("the ", "an " or "a ", checked in that
// order) is stripped before taking the first word; duplicate detection
// compares the normalized answers without stripping.
//
// Determinism: the letter and category decks are shuffled in newMatch from
// a hash of the player ids and the pot (never ctx.random), and later rounds
// draw from those decks, so every state transition is reproducible. Only
// randomMove uses ctx.random; computerMove is a deterministic function of
// the visible state (letter, categories, round, acting seat) — see
// computerAnswers below — so the UI reducer can reproduce it exactly.
const LETTERS = ["a", "b", "c", "d", "e", "f", "g", "h", "i", "j", "k", "l", "m", "n", "o", "p", "r", "s", "t", "w"];
const CATEGORIES = [
  "Animal", "Food", "City", "Country", "Movie title", "Book title",
  "Sport", "Profession", "Color", "Flower", "Tree", "River",
  "Musical instrument", "Toy", "Vehicle", "Clothing item", "Drink", "Fruit",
  "Vegetable", "School subject", "Holiday", "Song title", "Famous person",
  "Body part", "Household item", "Board game", "Ocean or sea", "Mountain",
  "Dessert", "Superhero"
];
const WORDS = {
  a: ["apple", "ant", "anchor", "arrow"], b: ["banana", "bear", "bridge", "button"],
  c: ["cat", "cake", "castle", "candle"], d: ["dog", "drum", "diamond", "door"],
  e: ["elephant", "egg", "engine", "eagle"], f: ["fish", "flower", "forest", "flag"],
  g: ["goat", "grape", "guitar", "garden"], h: ["horse", "house", "hat", "hammer"],
  i: ["island", "ice", "iron", "igloo"], j: ["juice", "jungle", "jacket", "jam"],
  k: ["kite", "kangaroo", "key", "kitchen"], l: ["lion", "lemon", "ladder", "lake"],
  m: ["monkey", "moon", "mountain", "milk"], n: ["nose", "night", "nest", "needle"],
  o: ["orange", "ocean", "owl", "onion"], p: ["pig", "pizza", "piano", "park"],
  r: ["rabbit", "river", "rainbow", "ring"], s: ["snake", "sun", "star", "soup"],
  t: ["tiger", "tree", "table", "train"], w: ["wolf", "water", "window", "whale"]
};
const RANDOM_POOL = ["apple", "banana", "cat", "dog", "sun", "tree", "river", "star", "moon", "fish", "bird", "cake", "lion", "wolf"];

function hashSeed(ctx) {
  let h = 2166136261 >>> 0;
  const s = ctx.players.map(function (p) { return p.id; }).join(",") + "|" + ctx.pot + "|" + ctx.players.length;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  return h >>> 0;
}
function makeRng(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6D2B79F5) | 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t = (t + Math.imul(t ^ (t >>> 7), t | 61)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
function shuffled(count, rng) {
  const out = [];
  for (let i = 0; i < count; i++) out.push(i);
  for (let i = count - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    const t = out[i]; out[i] = out[j]; out[j] = t;
  }
  return out;
}
function drawRound(s) {
  s.letter = LETTERS[s.letterDeck.pop()];
  const cats = [];
  for (let i = 0; i < 6; i++) cats.push(CATEGORIES[s.catDeck.pop()]);
  s.cats = cats;
}
function norm(a) { return a.trim().replace(/\s+/g, " ").toLowerCase(); }
function firstWord(n) {
  let w = n;
  if (w.indexOf("the ") === 0) w = w.slice(4);
  else if (w.indexOf("an ") === 0) w = w.slice(3);
  else if (w.indexOf("a ") === 0) w = w.slice(2);
  const sp = w.indexOf(" ");
  return sp === -1 ? w : w.slice(0, sp);
}
function scoreRound(s) {
  const n = s.scores.length;
  const pts = [], gained = [];
  for (let p = 0; p < n; p++) { pts.push([0, 0, 0, 0, 0, 0]); gained.push(0); }
  for (let c = 0; c < 6; c++) {
    const norms = s.answers.map(function (a) { return norm(a[c]); });
    for (let p = 0; p < n; p++) {
      const v = norms[p];
      if (!v) continue;
      let dup = false;
      for (let q = 0; q < n; q++) if (q !== p && norms[q] === v) { dup = true; break; }
      if (dup) continue;
      const fw = firstWord(v);
      if (fw && fw.charAt(0) === s.letter) { pts[p][c] = 1; gained[p]++; }
    }
  }
  for (let p = 0; p < n; p++) s.scores[p] += gained[p];
  return { pts: pts, gained: gained };
}
// Deterministic computer answers: a pure function of the visible state
// (letter, cats, round, acting seat). For each category, FNV-1a hash the
// string letter|round|seat|categoryIndex|category and index the letter's
// word bank with it. The declarative UI reducer embeds an identical copy
// of this algorithm (and of WORDS) and pre-fills the acting player's text
// controls with these answers, so a single Submit tap emits exactly the
// move computerMove returns. Empty string when the bank has no word.
function computerAnswers(letter, cats, round, seat) {
  const bank = WORDS[letter] || [];
  const answers = [];
  for (let c = 0; c < 6; c++) {
    if (!bank.length) { answers.push(""); continue; }
    const str = String(letter) + "|" + String(round) + "|" + String(seat) + "|" + String(c) + "|" + String(cats && cats[c] ? cats[c] : "");
    let h = 2166136261 >>> 0;
    for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 16777619); }
    answers.push(bank[(h >>> 0) % bank.length]);
  }
  return answers;
}
function payoutsFor(s, ctx) {
  const pot = ctx.pot;
  if (!pot) return {};
  let recips = s.winners.filter(function (seat) {
    const p = ctx.players[seat];
    return p && p.kind === "human" && p.active !== false;
  });
  if (!recips.length) {
    recips = [];
    ctx.players.forEach(function (p, i) { if (p.kind === "human" && p.active !== false) recips.push(i); });
  }
  if (!recips.length) return {};
  const base = Math.floor(pot / recips.length), rem = pot % recips.length, out = {};
  recips.forEach(function (seat, i) { out[ctx.players[seat].id] = base + (i < rem ? 1 : 0); });
  return out;
}

const game = {
  newMatch(ctx) {
    const n = ctx.players.length;
    const rng = makeRng(hashSeed(ctx));
    const s = {
      round: 1, letter: "a", cats: [], turn: 0,
      scores: [], answers: [], past: [],
      letterDeck: shuffled(LETTERS.length, rng),
      catDeck: shuffled(CATEGORIES.length, rng),
      over: false, winners: []
    };
    for (let i = 0; i < n; i++) { s.scores.push(0); s.answers.push(null); }
    drawRound(s);
    return { state: s, turn: [ctx.players[0].id] };
  },
  applyMove(state, id, move, ctx) {
    if (!state || typeof state !== "object" || state.over) throw new InvalidMove("invalid move");
    const seat = state.turn;
    if (!ctx.players[seat] || ctx.players[seat].id !== id) throw new InvalidMove("invalid move");
    if (!move || typeof move !== "object" || Array.isArray(move)) throw new InvalidMove("invalid move");
    if (move.type !== "answer") throw new InvalidMove("invalid move");
    if (!Array.isArray(move.answers) || move.answers.length !== 6) throw new InvalidMove("invalid move");
    for (let i = 0; i < 6; i++) {
      if (typeof move.answers[i] !== "string" || move.answers[i].length > 40) throw new InvalidMove("invalid move");
    }
    if (state.answers[seat] !== null) throw new InvalidMove("invalid move");
    const s = JSON.parse(JSON.stringify(state));
    s.answers[seat] = move.answers.slice();
    let next = -1;
    for (let j = seat + 1; j < s.answers.length; j++) if (s.answers[j] === null) { next = j; break; }
    if (next !== -1) { s.turn = next; return { state: s, turn: [ctx.players[next].id] }; }
    const scored = scoreRound(s);
    s.past.push({
      letter: s.letter, cats: s.cats.slice(),
      answers: s.answers.map(function (a) { return a.slice(); }),
      pts: scored.pts, gained: scored.gained
    });
    s.answers = s.answers.map(function () { return null; });
    if (s.round >= 3) {
      s.over = true;
      const best = Math.max.apply(null, s.scores);
      s.winners = [];
      s.scores.forEach(function (v, i) { if (v === best) s.winners.push(i); });
      s.turn = 0;
      return { state: s, turn: null, payouts: payoutsFor(s, ctx) };
    }
    s.round += 1;
    drawRound(s);
    s.turn = 0;
    return { state: s, turn: [ctx.players[0].id] };
  },
  viewFor(state, id, ctx) {
    let seat = -1;
    for (let i = 0; i < ctx.players.length; i++) if (ctx.players[i].id === id) seat = i;
    return {
      round: state.round, letter: state.letter, cats: state.cats.slice(),
      turn: state.turn, scores: state.scores.slice(),
      submitted: state.answers.map(function (a) { return a !== null; }),
      answers: state.answers.map(function (a, i) { return (i === seat && a) ? a.slice() : null; }),
      past: JSON.parse(JSON.stringify(state.past)),
      over: state.over, winners: state.winners.slice(), seat: seat
    };
  },
  computerMove(state, id, ctx) {
    return { type: "answer", answers: computerAnswers(state.letter, state.cats, state.round, state.turn) };
  },
  randomMove(state, id, ctx) {
    const answers = [];
    for (let c = 0; c < 6; c++) {
      const r = ctx.random();
      if (r < 0.4) answers.push("");
      else if (r < 0.8) answers.push(RANDOM_POOL[Math.floor(ctx.random() * RANDOM_POOL.length)]);
      else answers.push(state.letter + "word" + (10 + Math.floor(ctx.random() * 90)));
    }
    return { type: "answer", answers: answers };
  }
};

declarative_ui.ui_code:
const SOURCE_STRINGS = {"title": "Scattergories", "turn_player": "Player {n} to answer", "finished": "Finished", "round_letter": "Round {r} of 3 - Letter {l}", "scores": "Scores", "player_score": "Player {n}: {v}", "done_word": "answered", "answering_word": "answering", "waiting_word": "waiting", "submit": "Submit answers", "your_answers": "Your answers: {v}", "round_line": "Round {r}: Letter {l}", "p_gain": "P{n} +{v}", "winner": "Player {n} wins", "tie": "Tie between Players {v}", "server_invalid_move": "invalid move"};
var gameUI = {
  reduce: function (message, localState) {
    var m = message.type === "ui_event" ? message.state_changed : message;
    var s = m.view || m.state || {};
    var strings = {};
    var k;
    for (k in SOURCE_STRINGS) strings[k] = SOURCE_STRINGS[k];
    if (m.strings) for (k in m.strings) strings[k] = m.strings[k];
    function t(key, args) {
      var txt = strings[key] || key;
      if (!args) return txt;
      return txt.replace(/\{(\w+)\}/g, function (_, name) { return String(args[name] === undefined ? "" : args[name]); });
    }
    var active = m.status === "ongoing" && !m.replay && m.acting_for_player_index !== null && m.acting_for_player_index !== undefined;
    var canAct = !!(active && !s.over && s.seat !== undefined && s.seat === s.turn && m.acting_for_player_index === s.turn);
    // Replica of the server's computerMove: WORDS and the FNV-1a indexing in
    // suggestedAnswers are identical copies of the server code, and both
    // are pure functions of the visible state (letter, cats, round, acting
    // seat = turn), so the pre-filled controls emit exactly computerMove.
    var WORDS = {
      a: ["apple", "ant", "anchor", "arrow"], b: ["banana", "bear", "bridge", "button"],
      c: ["cat", "cake", "castle", "candle"], d: ["dog", "drum", "diamond", "door"],
      e: ["elephant", "egg", "engine", "eagle"], f: ["fish", "flower", "forest", "flag"],
      g: ["goat", "grape", "guitar", "garden"], h: ["horse", "house", "hat", "hammer"],
      i: ["island", "ice", "iron", "igloo"], j: ["juice", "jungle", "jacket", "jam"],
      k: ["kite", "kangaroo", "key", "kitchen"], l: ["lion", "lemon", "ladder", "lake"],
      m: ["monkey", "moon", "mountain", "milk"], n: ["nose", "night", "nest", "needle"],
      o: ["orange", "ocean", "owl", "onion"], p: ["pig", "pizza", "piano", "park"],
      r: ["rabbit", "river", "rainbow", "ring"], s: ["snake", "sun", "star", "soup"],
      t: ["tiger", "tree", "table", "train"], w: ["wolf", "water", "window", "whale"]
    };
    function suggestedAnswers() {
      var bank = WORDS[s.letter] || [];
      var viewCats = s.cats || [];
      var out = [];
      for (var sc = 0; sc < 6; sc++) {
        if (!bank.length) { out.push(""); continue; }
        var str = String(s.letter) + "|" + String(s.round) + "|" + String(s.turn) + "|" + String(sc) + "|" + String(viewCats[sc] ? viewCats[sc] : "");
        var hh = 2166136261 >>> 0;
        for (var hi = 0; hi < str.length; hi++) { hh ^= str.charCodeAt(hi); hh = Math.imul(hh, 16777619); }
        out.push(bank[(hh >>> 0) % bank.length]);
      }
      return out;
    }
    var key = String(m.move_count || 0) + "/" + String(s.round || 1) + "/" + String(s.turn || 0);
    var local = localState || {};
    // Pre-fill the acting player's controls with computerMove's answers on
    // a fresh turn (new key, or a blank placeholder local for this key that
    // was never pre-filled). filled_for tags the move_count/key the answers
    // belong to; once it matches, answers are kept verbatim so values the
    // user typed (change events) are never overridden within this turn.
    if (local.key !== key || !local.answers || local.answers.length !== 6) {
      local = { key: key, answers: canAct ? suggestedAnswers() : ["", "", "", "", "", ""], filled_for: canAct ? key : null };
    } else if (canAct && local.filled_for !== key) {
      local = { key: key, answers: suggestedAnswers(), filled_for: key };
    }
    var makeMove = null;
    if (message.type === "ui_event" && canAct) {
      var ev = message.event || {};
      if (ev.type === "change" && typeof ev.id === "string" && ev.id.indexOf("ans") === 0) {
        var idx = parseInt(ev.id.slice(3), 10);
        if (idx >= 0 && idx < 6) { local.answers[idx] = String(ev.value === null || ev.value === undefined ? "" : ev.value).slice(0, 40); local.filled_for = key; }
      } else if (ev.type === "tap" && ev.id === "submit") {
        var ans = [];
        for (var ai = 0; ai < 6; ai++) ans.push(String(local.answers[ai] || "").slice(0, 40));
        makeMove = { type: "answer", answers: ans };
      }
    }
    var pieces = [], targets = [], controls = [], labels = [];
    labels.push({ id: "title", text: t("title"), x: 24, y: 12, font_size: 26 });
    labels.push({ id: "round", text: t("round_letter", { r: s.round || 1, l: String(s.letter || "").toUpperCase() }), x: 24, y: 46, font_size: 19 });
    var turnText;
    if (s.over) {
      if (s.winners && s.winners.length > 1) turnText = t("tie", { v: s.winners.map(function (w) { return String(w + 1); }).join(", ") });
      else if (s.winners && s.winners.length === 1) turnText = t("winner", { n: s.winners[0] + 1 });
      else turnText = t("finished");
    } else {
      turnText = t("turn_player", { n: (s.turn || 0) + 1 });
    }
    labels.push({ id: "turn", text: turnText, x: 24, y: 74, font_size: 18 });
    pieces.push({ id: "letter", type: "letterBadge", board: "main", position: { x: 72, y: 66 }, text: String(s.letter || "").toUpperCase(), actions: [] });
    var cats = s.cats || [];
    for (var c = 0; c < cats.length && c < 6; c++) {
      pieces.push({ id: "cat_" + c, type: "catText", board: "main", position: { x: 330, y: 38 + c * 56 }, text: String(c + 1) + ". " + cats[c], actions: [] });
    }
    var submitted = s.submitted || [];
    for (var p = 0; p < submitted.length; p++) {
      pieces.push({ id: "dot_" + p, type: submitted[p] ? "dotOn" : "dotOff", board: "main", position: { x: 64 + p * 48, y: 392 }, text: String(p + 1), actions: [] });
    }
    var lines = [];
    lines.push(t("scores"));
    var scores = s.scores || [];
    for (var pi = 0; pi < scores.length; pi++) {
      var line = t("player_score", { n: pi + 1, v: scores[pi] });
      if (!s.over) line += " - " + t(submitted[pi] ? "done_word" : pi === s.turn ? "answering_word" : "waiting_word");
      lines.push(line);
    }
    if (s.seat !== undefined && s.seat >= 0 && s.answers && s.answers[s.seat]) {
      lines.push(t("your_answers", { v: s.answers[s.seat].map(function (a) { return a === "" ? "-" : a; }).join(", ") }));
    }
    var past = s.past || [];
    for (var ri = 0; ri < past.length; ri++) {
      var gains = [];
      for (var gi = 0; gi < past[ri].gained.length; gi++) gains.push(t("p_gain", { n: gi + 1, v: past[ri].gained[gi] }));
      lines.push(t("round_line", { r: ri + 1, l: String(past[ri].letter || "").toUpperCase() }) + " - " + gains.join(", "));
    }
    for (var li = 0; li < lines.length; li++) {
      labels.push({ id: "line_" + li, text: lines[li], x: 24, y: 552 + li * 19, font_size: 15 });
    }
    if (canAct) {
      for (var ci = 0; ci < 6; ci++) {
        controls.push({ id: "ans" + ci, kind: "text", label: cats[ci] || "", value: local.answers[ci] });
      }
      controls.push({ id: "submit", kind: "button", label: t("submit") });
    }
    var out = { scene: { pieces: pieces, targets: targets, controls: controls, labels: labels }, local_state: local };
    if (makeMove) out.make_move = makeMove;
    return out;
  }
};
